def zeroNoiseLikelihood (mu : ThresholdProfile) (o : Obs) : ℝ :=
  if o.2.2 = 1 then 2*(mu (Set.projIcc 0 1 zero_le_one o.2.1) : ℝ)
  else 2*(1-(mu (Set.projIcc 0 1 zero_le_one o.2.1) : ℝ))

